items.solution:
function processRefunds(accounts, clock, gateway) {
  const refunded = [];
  for (const acct of accounts) {
    if (clock() > acct.renewalDate && acct.chargeId) {
      gateway.refund(acct.chargeId);
      refunded.push(acct.id);
    }
  }
  return refunded;
}
